import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { TrendingUp, Award, Target, CalendarCheck } from 'lucide-react';
import axios from 'axios';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (user) {
            fetchStats();
        }
    }, [user]);

    const fetchStats = async () => {
        try {
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch stats');
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const statsCards = [
        { label: 'Completion Rate', value: `${Math.round(stats?.completionPercentage || 0)}%`, icon: TrendingUp, color: 'text-green-600' },
        { label: 'Days Completed', value: `${stats?.completedDays || 0}/${stats?.totalDays || 30}`, icon: CalendarCheck, color: 'text-blue-600' },
        { label: 'Streak', value: `${stats?.currentStreak || 0} days`, icon: Award, color: 'text-purple-600' },
        { label: 'Target', value: '30 days', icon: Target, color: 'text-orange-600' },
    ];

    return (
        <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                {statsCards.map((stat, index) => {
                    const Icon = stat.icon;
                    return (
                        <div key={index} className="bg-white rounded-lg shadow-lg p-6">
                            <div className="flex items-center justify-between">
                                <div>
                                    <p className="text-sm text-gray-600">{stat.label}</p>
                                    <p className="text-2xl font-bold mt-1">{stat.value}</p>
                                </div>
                                <Icon className={`${stat.color} w-8 h-8`} />
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="bg-gradient-to-r from-blue-500 to-purple-600 rounded-lg shadow-lg p-8 text-white">
                <h2 className="text-2xl font-bold mb-2">Keep Going! 🚀</h2>
                <p className="opacity-90">
                    You're making great progress! Remember: Consistency is key to mastering development skills.
                </p>
                <div className="mt-4 flex gap-4">
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#CodeEveryday</span>
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#NeverGiveUp</span>
                    <span className="px-3 py-1 bg-white/20 rounded-full text-sm">#YouCanDoIt</span>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
